//go:build parity

// Parity test against the reference Python classifier (PRICING_CONCEPTS.md
// §5 non-negotiable #2). testdata/parity_fixtures.json is pre-generated by
// reference/gen_parity.py running price_spells.py over random synthetic
// series; this test replays the same raw rows through the Go port and
// diffs the resulting labels. Re-run gen_parity.py and re-check in the JSON
// whenever price_spells.py or internal/pricing's logic changes, then run:
//
//	go test -tags parity ./internal/pricing
package pricing

import (
	"encoding/json"
	"os"
	"sort"
	"testing"
	"time"

	"retail-prices/internal/quality"
)

type fixtureRow struct {
	ProductID string  `json:"product_id"`
	Date      string  `json:"date"`
	Price     float64 `json:"price"`
}

type fixtureSpell struct {
	ProductID    string   `json:"product_id"`
	Price        float64  `json:"price"`
	Start        string   `json:"start"`
	Days         int      `json:"days"`
	Label        string   `json:"label"`
	RegularPrice *float64 `json:"regular_price"`
}

type fixtures struct {
	Rows   []fixtureRow   `json:"rows"`
	Spells []fixtureSpell `json:"spells"`
}

func TestParityAgainstReferencePython(t *testing.T) {
	data, err := os.ReadFile("testdata/parity_fixtures.json")
	if err != nil {
		t.Fatalf("reading fixtures (run reference/gen_parity.py first): %v", err)
	}
	var fx fixtures
	if err := json.Unmarshal(data, &fx); err != nil {
		t.Fatalf("parsing fixtures: %v", err)
	}

	byProduct := map[string][]quality.Observation{}
	for _, r := range fx.Rows {
		ts, err := time.Parse("2006-01-02T15:04:05", r.Date)
		if err != nil {
			// gen_parity.py emits date.isoformat() for a date-only value,
			// which is just "2006-01-02".
			ts, err = time.Parse("2006-01-02", r.Date)
			if err != nil {
				t.Fatalf("parsing date %q: %v", r.Date, err)
			}
		}
		byProduct[r.ProductID] = append(byProduct[r.ProductID], quality.Observation{Price: r.Price, ScrapedAt: ts})
	}

	wantByProduct := map[string][]fixtureSpell{}
	for _, s := range fx.Spells {
		wantByProduct[s.ProductID] = append(wantByProduct[s.ProductID], s)
	}

	products := make([]string, 0, len(byProduct))
	for pid := range byProduct {
		products = append(products, pid)
	}
	sort.Strings(products)

	mismatches := 0
	for _, pid := range products {
		obs := byProduct[pid]
		sort.Slice(obs, func(i, j int) bool { return obs[i].ScrapedAt.Before(obs[j].ScrapedAt) })

		intervals := quality.BuildIntervals(obs)
		got, _ := Classify(intervals, DefaultParams, nil)
		want := wantByProduct[pid]

		if len(got) != len(want) {
			t.Errorf("%s: got %d spells, want %d (reference)", pid, len(got), len(want))
			mismatches++
			continue
		}
		for i, w := range want {
			g := got[i]
			wantStart, err := time.Parse("2006-01-02", w.Start)
			if err != nil {
				t.Fatalf("parsing want start %q: %v", w.Start, err)
			}
			if g.Price != w.Price || !g.Start.Equal(wantStart) || g.Days != w.Days || g.Label != w.Label {
				t.Errorf("%s spell %d: got {price=%v start=%s days=%d label=%s}, want {price=%v start=%s days=%d label=%s}",
					pid, i, g.Price, g.Start.Format("2006-01-02"), g.Days, g.Label,
					w.Price, w.Start, w.Days, w.Label)
				mismatches++
			}
			switch {
			case w.RegularPrice == nil && g.RegularPrice != nil:
				t.Errorf("%s spell %d: got regular_price=%v, want nil", pid, i, *g.RegularPrice)
				mismatches++
			case w.RegularPrice != nil && (g.RegularPrice == nil || *g.RegularPrice != *w.RegularPrice):
				t.Errorf("%s spell %d: got regular_price=%v, want %v", pid, i, g.RegularPrice, *w.RegularPrice)
				mismatches++
			}
		}
	}
	if mismatches > 0 {
		t.Fatalf("%d mismatches against the reference Python classifier", mismatches)
	}
}
